import React from 'react';
import { Container, Row, Col, Table, Button } from 'reactstrap';
import useFetch from '../../hooks/useFetch';
import { BASE_URL } from '../../utils/config';

const ManageBookings = () => {
   // 1. Lấy danh sách booking từ API
   const { data: bookings, loading, error } = useFetch(`${BASE_URL}/booking`);

   // 2. Hàm xử lý xóa Đơn hàng
   const deleteHandler = async (id) => {
      if (window.confirm("Bạn có chắc chắn muốn xóa đơn hàng này?")) {
         const token = localStorage.getItem('token');
         try {
            const res = await fetch(`${BASE_URL}/booking/${id}`, {
               method: 'DELETE',
               headers: {
                  'Authorization': `Bearer ${token}`
               }
            });

            if (res.ok) {
               alert("Xóa đơn hàng thành công!");
               window.location.reload();
            } else {
               const result = await res.json();
               alert(result.message);
            }
         } catch (err) {
            alert("Lỗi server không thể xóa!");
         }
      }
   };

   return (
      <section>
         <Container>
            <Row>
               <Col lg='12' className="mb-4 mt-5">
                  <h2 className="manage__title text-primary fw-bold">Quản lý Đơn hàng (Bookings)</h2>
                  <p className="text-muted">Danh sách khách hàng đã đặt tour trên hệ thống</p>
               </Col>

               <Col lg='12'>
                  <div className="table__wrapper shadow-sm p-3 bg-white rounded">
                     <Table striped bordered hover responsive className="text-center align-middle">
                        <thead className="table-dark">
                           <tr>
                              <th>Khách hàng</th>
                              <th>Tên Tour</th>
                              <th>Số người</th>
                              <th>Ngày đi</th>
                              <th>Số điện thoại</th>
                              <th>Tổng tiền</th>
                              <th>Thao tác</th>
                           </tr>
                        </thead>
                        <tbody>
                           {loading && <tr><td colSpan='7' className="py-5">Đang tải dữ liệu...</td></tr>}
                           {error && <tr><td colSpan='7' className="text-danger py-5">{error}</td></tr>}
                           
                           {!loading && !error && bookings?.map(booking => (
                              <tr key={booking._id}>
                                 <td className="text-start">
                                    <div><strong>{booking.fullName}</strong></div>
                                    <small className="text-muted">{booking.userEmail}</small>
                                 </td>
                                 <td className="text-start">{booking.tourName}</td>
                                 <td>{booking.guestSize}</td>
                                 <td>{new Date(booking.bookAt).toLocaleDateString('vi-VN')}</td>
                                 <td>{booking.phone}</td>
                                 <td className="text-end text-danger fw-bold">
                                    {/* Sử dụng toLocaleString để thêm dấu chấm cách phần nghìn */}
                                    {Number(booking.totalAmount || 0).toLocaleString('vi-VN')} đ
                                 </td>
                                 <td>
                                    <Button 
                                       color="danger" 
                                       size="sm"
                                       onClick={() => deleteHandler(booking._id)}
                                    >
                                       Xóa
                                    </Button>
                                 </td>
                              </tr>
                           ))}

                           {!loading && !error && bookings?.length === 0 && (
                              <tr><td colSpan='7' className="py-5">Chưa có đơn hàng nào.</td></tr>
                           )}
                        </tbody>
                     </Table>
                  </div>
               </Col>
            </Row>
         </Container>
      </section>
   );
};

export default ManageBookings;
